1	/**
2	 * Integration tests: POST /api/payments/charge
3	 *
4	 * Stripe + Supabase mocked. All tests run unconditionally.
5	 *
6	 * Coverage (8 tests):
7	 *  1. Auth required — 401 when unauthenticated
8	 *  2. Studio scope — 403 if not a studio member
9	 *  3. Rate limit applied — 429 when rate limited
10	 *  4. Body validation — 400 on Zod errors
11	 *  5. Capability gate response — 403 with { error, reason, message }
12	 *  6. Country drift — 422 response
13	 *  7. Happy path — 200 with { payment_intent_id, status, amount_charged_cents, deposit_transaction_id }
14	 *  8. Stripe error — 502 sanitized response
15	 */
16	
17	import { describe, it, expect, vi, beforeEach } from 'vitest'
18	import { NextRequest } from 'next/server'
19	import { CapabilityGateError } from '@/lib/payments/capability-gate'
20	
21	// ---------------------------------------------------------------------------
22	// Controllable mock state
23	// ---------------------------------------------------------------------------
24	
25	type MockUser = { id: string } | null
26	let mockUser: MockUser = { id: 'user-owner-001' }
27	let mockMember: {
28	  studio_id: string
29	  role: string
30	} | null = { studio_id: 'studio-001', role: 'owner' }
31	let mockRateLimitSuccess = true
32	
33	// What createSessionPaymentIntent returns
34	const mockCreateSessionPI = vi.fn()
35	
36	// ---------------------------------------------------------------------------
37	// Module mocks
38	// ---------------------------------------------------------------------------
39	
40	vi.mock('@/lib/supabase/server', () => ({
41	  createClient: vi.fn(async () => ({
42	    auth: {
43	      getUser: vi.fn(async () => ({ data: { user: mockUser }, error: null })),
44	    },
45	    from: vi.fn((table: string) => {
46	      if (table === 'studio_members') {
47	        return {
48	          select: vi.fn(() => ({
49	            eq: vi.fn(() => ({
50	              is: vi.fn(() => ({
51	                order: vi.fn(() => ({
52	                  limit: vi.fn(() => ({
53	                    single: vi.fn(async () => ({
54	                      data: mockMember,
55	                      error: mockMember ? null : { message: 'Not found' },
56	                    })),
57	                  })),
58	                })),
59	              })),
60	            })),
61	          })),
62	        }
63	      }
64	      if (table === 'bookings') {
65	        return {
66	          select: vi.fn(() => ({
67	            eq: vi.fn(() => ({
68	              eq: vi.fn(() => ({
69	                single: vi.fn(async () => ({
70	                  data: {
71	                    id: '00000000-0000-4000-8000-000000000001',
72	                    client_id: '00000000-0000-4000-8000-000000000005',
73	                    artist_id: '00000000-0000-4000-8000-000000000004',
74	                    project_id: '00000000-0000-4000-8000-000000000002',
75	                    status: 'confirmed',
76	                  },
77	                  error: null,
78	                })),
79	              })),
80	            })),
81	          })),
82	        }
83	      }
84	      if (table === 'clients') {
85	        return {
86	          select: vi.fn(() => ({
87	            eq: vi.fn(() => ({
88	              eq: vi.fn(() => ({
89	                single: vi.fn(async () => ({
90	                  data: { id: '00000000-0000-4000-8000-000000000005', stripe_customer_id: 'cus_test_001' },
91	                  error: null,
92	                })),
93	              })),
94	            })),
95	          })),
96	        }
97	      }
98	      if (table === 'stripe_connected_accounts') {
99	        // Handles up to 3 levels of .eq() chaining (studio type + artist type)
100	        const connAccSingle = vi.fn(async () => ({
101	          data: { account_id: 'acct_studio_001', onboarding_status: 'active' },
102	          error: null,
103	        }))
104	        return {
105	          select: vi.fn(() => ({
106	            eq: vi.fn(() => ({
107	              eq: vi.fn(() => ({
108	                single: connAccSingle,
109	                eq: vi.fn(() => ({
110	                  single: vi.fn(async () => ({ data: null, error: { message: 'No artist account' } })),
111	                })),
112	              })),
113	            })),
114	          })),
115	        }
116	      }
117	      if (table === 'studios') {
118	        return {
119	          select: vi.fn(() => ({
120	            eq: vi.fn(() => ({
121	              single: vi.fn(async () => ({
122	                data: { default_currency: 'usd' },
123	                error: null,
124	              })),
125	            })),
126	          })),
127	        }
128	      }
129	      if (table === 'team_members') {
130	        return {
131	          select: vi.fn(() => ({
132	            eq: vi.fn(() => ({
133	              eq: vi.fn(() => ({
134	                single: vi.fn(async () => ({ data: null, error: { message: 'Not found' } })),
135	              })),
136	            })),
137	          })),
138	        }
139	      }
140	      return {
141	        select: vi.fn(() => ({
142	          eq: vi.fn(() => ({
143	            single: vi.fn(async () => ({ data: null, error: null })),
144	          })),
145	        })),
146	      }
147	    }),
148	  })),
149	  createServiceRoleClient: vi.fn(() => {
150	    // Service role client handles S16-schema reads (clients, stripe_connected_accounts,
151	    // team_members, studios) and SAGA RPC writes.
152	    const makeChain = (leafData: unknown, leafError: unknown = null): unknown => ({
153	      select: vi.fn(() => makeChain(leafData, leafError)),
154	      eq: vi.fn(() => makeChain(leafData, leafError)),
155	      is: vi.fn(() => makeChain(leafData, leafError)),
156	      order: vi.fn(() => makeChain(leafData, leafError)),
157	      limit: vi.fn(() => makeChain(leafData, leafError)),
158	      single: vi.fn(async () => ({ data: leafData, error: leafError })),
159	      maybeSingle: vi.fn(async () => ({ data: leafData, error: leafError })),
160	    })
161	
162	    return {
163	      rpc: vi.fn(async () => ({ data: null, error: null })),
164	      from: vi.fn((table: string) => {
165	        if (table === 'clients') {
166	          return makeChain({ id: '00000000-0000-4000-8000-000000000005', stripe_customer_id: 'cus_test_001' })
167	        }
168	        if (table === 'stripe_connected_accounts') {
169	          return makeChain({ account_id: 'acct_studio_001', onboarding_status: 'active' })
170	        }
171	        if (table === 'team_members') {
172	          return makeChain(null, { message: 'Not found' })
173	        }
174	        if (table === 'studios') {
175	          return makeChain({ default_currency: 'usd' })
176	        }
177	        return makeChain(null)
178	      }),
179	    }
180	  }),
181	}))
182	
183	vi.mock('@/lib/rate-limit', () => ({
184	  authedRatelimit: {
185	    limit: vi.fn(async () => ({
186	      success: mockRateLimitSuccess,
187	      limit: 60,
188	      remaining: 59,
189	      reset: Date.now() + 60000,
190	    })),
191	  },
192	}))
193	
194	vi.mock('@/lib/rate-limit/get-client-ip', () => ({
195	  getClientIp: vi.fn(() => '127.0.0.1'),
196	}))
197	
198	vi.mock('@/lib/stripe/charges', () => ({
199	  createSessionPaymentIntent: (...args: unknown[]) => mockCreateSessionPI(...args),
200	}))
201	
202	vi.mock('@/lib/audit', () => ({
203	  logAuditAction: vi.fn().mockResolvedValue(undefined),
204	}))
205	
206	vi.mock('@/lib/logger', () => ({
207	  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
208	}))
209	
210	// ---------------------------------------------------------------------------
211	// Route import (after mocks)
212	// ---------------------------------------------------------------------------
213	
214	const { POST } = await import('@/app/api/payments/charge/route')
215	
216	// ---------------------------------------------------------------------------
217	// Helpers
218	// ---------------------------------------------------------------------------
219	
220	function makeRequest(body: Record<string, unknown>): NextRequest {
221	  return new NextRequest('http://localhost/api/payments/charge', {
222	    method: 'POST',
223	    headers: { 'Content-Type': 'application/json' },
224	    body: JSON.stringify(body),
225	  })
226	}
227	
228	function validBody() {
229	  return {
230	    bookingId: '00000000-0000-4000-8000-000000000001',
231	    sessionId: '00000000-0000-4000-8000-000000000003',
232	    baseAmountCents: 15000,
233	    tipAmountCents: 500,
234	    depositDrawdownCents: 0,
235	    paymentMethodId: 'pm_test_abc123',
236	  }
237	}
238	
239	// ---------------------------------------------------------------------------
240	// Tests
241	// ---------------------------------------------------------------------------
242	
243	describe('POST /api/payments/charge', () => {
244	  beforeEach(() => {
245	    vi.clearAllMocks()
246	    mockUser = { id: 'user-owner-001' }
247	    mockMember = { studio_id: 'studio-001', role: 'owner' }
248	    mockRateLimitSuccess = true
249	
250	    mockCreateSessionPI.mockResolvedValue({
251	      paymentIntentId: 'pi_test_result_001',
252	      clientSecret: 'pi_test_result_001_secret',
253	      status: 'succeeded',
254	      depositTransactionId: null,
255	      amountChargedCents: 15500,
256	    })
257	  })
258	
259	  it('returns 401 when unauthenticated', async () => {
260	    mockUser = null
261	    const res = await POST(makeRequest(validBody()))
262	    expect(res.status).toBe(401)
263	  })
264	
265	  it('returns 403 when not a studio member', async () => {
266	    mockMember = null
267	    const res = await POST(makeRequest(validBody()))
268	    expect(res.status).toBe(403)
269	  })
270	
271	  it('returns 429 when rate limited', async () => {
272	    mockRateLimitSuccess = false
273	    const res = await POST(makeRequest(validBody()))
274	    expect(res.status).toBe(429)
275	  })
276	
277	  it('returns 400 on Zod validation failure (missing required fields)', async () => {
278	    const res = await POST(makeRequest({ bookingId: 'not-a-uuid' }))
279	    expect(res.status).toBe(400)
280	    const body = await res.json() as { error: string; issues: unknown[] }
281	    expect(body.error).toBe('Validation failed')
282	    expect(Array.isArray(body.issues)).toBe(true)
283	  })
284	
285	  it('capability gate failure — returns 403 with { error, reason, message }', async () => {
286	    const { CapabilityGateError: CGE } = await import('@/lib/payments/capability-gate')
287	    mockCreateSessionPI.mockRejectedValueOnce(
288	      new CGE('no_connected_account', 'Set up in-studio payments first.', 403),
289	    )
290	
291	    const res = await POST(makeRequest(validBody()))
292	    expect(res.status).toBe(403)
293	
294	    const body = await res.json() as { error: string; reason: string; message: string }
295	    expect(body.error).toBe('capability_gate')
296	    expect(body.reason).toBe('no_connected_account')
297	    expect(typeof body.message).toBe('string')
298	    expect(body.message.length).toBeGreaterThan(0)
299	  })
300	
301	  it('country drift — createSessionPaymentIntent throws CapabilityGateError with reason=country_drift → 422', async () => {
302	    const { CapabilityGateError: CGE } = await import('@/lib/payments/capability-gate')
303	    mockCreateSessionPI.mockRejectedValueOnce(
304	      new CGE('country_drift', 'Studio country no longer matches the Stripe account country.', 422),
305	    )
306	
307	    const res = await POST(makeRequest(validBody()))
308	    expect(res.status).toBe(422)
309	
310	    const body = await res.json() as { error: string; reason: string }
311	    expect(body.error).toBe('capability_gate')
312	    expect(body.reason).toBe('country_drift')
313	  })
314	
315	  it('happy path — returns 200 with { payment_intent_id, status, amount_charged_cents, deposit_transaction_id }', async () => {
316	    const res = await POST(makeRequest(validBody()))
317	    expect(res.status).toBe(200)
318	
319	    const body = await res.json() as {
320	      payment_intent_id: string
321	      status: string
322	      amount_charged_cents: number
323	      deposit_transaction_id: string | null
324	    }
325	    expect(body.payment_intent_id).toBe('pi_test_result_001')
326	    expect(body.status).toBe('succeeded')
327	    expect(typeof body.amount_charged_cents).toBe('number')
328	    expect('deposit_transaction_id' in body).toBe(true)
329	  })
330	
331	  it('Stripe error — returns 502 with sanitized error (no internal Stripe details)', async () => {
332	    mockCreateSessionPI.mockRejectedValueOnce(
333	      new Error('Your card was declined. [stripe internal code: card_decline_rate_limit_exceeded]'),
334	    )
335	
336	    const res = await POST(makeRequest(validBody()))
337	    expect(res.status).toBe(502)
338	
339	    const body = await res.json() as { error: string }
340	    expect(typeof body.error).toBe('string')
341	    // Must be truncated to 200 chars
342	    expect(body.error.length).toBeLessThanOrEqual(200)
343	  })
344	})
