// Test 5a: RPC is called with p_studio_id and p_year; result is ordered by total_paid_cents DESC.
it('RPC called with p_studio_id + p_year; artists ordered by total_paid_cents DESC', async () => {
  const artists: Nec1099AggregateArtistRow[] = [
    makeArtistRow({ artist_id: 'a1', total_paid_cents: cents(80000), nec_threshold_met: true }),
    makeArtistRow({ artist_id: 'a2', total_paid_cents: cents(50000), nec_threshold_met: false }),
  ]

  const mockResult: Nec1099AggregateResult = {
    year: 2025,
    studio_id: 'studio-order-test',
    artists,
    total_artists: 2,
    threshold_met_count: 1,
  }

  const calls: Array<{ fn: string; args: Record<string, unknown> }> = []
  const { _rpcFn } = makeRpcMock(async (fn, args) => {
    calls.push({ fn, args })
    return { data: mockResult, error: null }
  })

  const { data } = await _rpcFn(RPC.NEC_1099_AGGREGATE, {
    p_studio_id: 'studio-order-test',
    p_year: 2025,
  })

  // RPC was called with correct params
  expect(calls).toHaveLength(1)
  expect(calls[0].fn).toBe(RPC.NEC_1099_AGGREGATE)
  expect(calls[0].args.p_studio_id).toBe('studio-order-test')
  expect(calls[0].args.p_year).toBe(2025)

  const result = data as Nec1099AggregateResult
  // First artist has the highest total — ordered DESC
  expect(result.artists[0].total_paid_cents).toBeGreaterThan(result.artists[1].total_paid_cents)
})

// Test 6: total_artists includes ALL artists regardless of threshold status.
